-- ── category_addons ─────────────────────────────────────────────

CREATE TABLE category_addons (
    id                INTEGER PRIMARY KEY AUTOINCREMENT,
    category_id       INTEGER NOT NULL REFERENCES product_categories(id) ON DELETE CASCADE,
    addon_category_id INTEGER NOT NULL REFERENCES product_categories(id) ON DELETE CASCADE,
    min_select        INTEGER NOT NULL DEFAULT 0,  -- mínimo de escolhas (0 = opcional)
    max_select        INTEGER NOT NULL DEFAULT 0,  -- máximo de escolhas (0 = sem limite)
    free_qty          INTEGER NOT NULL DEFAULT 0,  -- quantas escolhas saem de graça
    sort_order        INTEGER NOT NULL DEFAULT 0,
    active            INTEGER NOT NULL DEFAULT 1,
    created_at        REAL    NOT NULL,
    UNIQUE(category_id, addon_category_id)
);

INSERT OR REPLACE INTO "category_addons" ("id", "category_id", "addon_category_id", "min_select", "max_select", "free_qty", "sort_order", "active", "created_at") VALUES (1, 1, 8, 0, 1, 0, 1, 1, 1790994005.6273093);
